/// The class of one character, before the optional hyphen is taken out
/// of it: see [`crate::class_of`].
pub(crate) fn class_of(character: char) -> Class {
    let code = character as u32;
    let after = CLASSES.partition_point(|(first, _)| *first <= code);
    CLASSES[after - 1].1
}

/// Whether the tables are in order and leave no character out, which is
/// what the searches above take for granted.
#[cfg(test)]
pub(crate) fn in_order() -> bool {
    CLASSES[0].0 == 0 && CLASSES.windows(2).all(|pair| pair[0].0 < pair[1].0)
}
